practice.solution:
import math

def sin_deg(degrees):
    return math.sin(math.radians(degrees))

n = int(input())
for i in range(n):
    A = int(input())
    a = int(input())
    b = int(input())
    print(f"A = {A}, a = {a}, b = {b}")
    s = b * sin_deg(A) / a
    print(f"  sin B = {s:.4f}")
    found = 0
    if s > 1 + 1e-9:
        print("  sin B > 1, so no triangle")
        candidates = []
    elif abs(s - 1) < 1e-9:
        candidates = [90]
    else:
        B1 = math.degrees(math.asin(s))
        candidates = [B1, 180 - B1]
    for B in candidates:
        if A + B < 180 - 1e-9:
            found = found + 1
            C = 180 - A - B
            c = a * sin_deg(C) / sin_deg(A)
            print(f"  B = {B:.2f}, C = {C:.2f}, c = {c:.2f}")
        else:
            print(f"  B = {B:.2f} leaves no room for C")
    print(f"  triangles: {found}")
